// Continue from the actually saved full initial field/acceleration. No mass,
// canonical topology, old CONTROL or completed transfer queries are replayed.
static R curvature_witness(const material_full::Owned&m,size_t s,int compact,
        const std::array<md::Vec,2>&a,const GfsEnrichConfig&cfg,STPoint&point_out){
    const auto&t=m.f.triangle[s];const auto&r=m.rule[s];double X[3],Y[3];int edges[3],count=0;
    for(int j=0;j<3;j++){X[j]=t.vertex[j][0];Y[j]=t.vertex[j][1];int k=(j+1)%3;double bx=t.vertex[j][0]-r.anchor[0],by=t.vertex[j][1]-r.anchor[1],cx=t.vertex[k][0]-r.anchor[0],cy=t.vertex[k][1]-r.anchor[1],jac=bx*cy-by*cx;if(j==r.anchor_edge||(bx==0&&by==0)||(cx==0&&cy==0))jac=0;if(jac>0)edges[count++]=j;}
    int angular=compact%cfg.na,radial=(compact/cfg.na)%cfg.nr,segment=(compact/(cfg.na*cfg.nr))%r.ns,k=compact/(cfg.na*cfg.nr*r.ns);need(k<count,"saved worst curvature compact index");int original=((edges[k]*r.ns+segment)*cfg.nr+radial)*cfg.na+angular;GfsMomentPolygon poly={X,Y,3,0};STPoint q={};q.triangle=s;q.boundary=-1;need(gfs_enrich_quad(poly,&cfg,&r,original,&q.X,&q.Y,&q.weight)&&q.weight>0,"saved worst curvature point");double u[4];need(gfs_enrich_reference(&cfg,q.X+12,q.Y+12,u,0,0),"saved worst curvature density");q.rho=u[0];
    R ux=R(X[1])-X[0],uy=R(Y[1])-Y[0],vx=R(X[2])-X[0],vy=R(Y[2])-Y[0],dx=R(q.X)-X[0],dy=R(q.Y)-Y[0],det=ux*vy-uy*vx;q.l[1]=(dx*vy-dy*vx)/det;q.l[2]=(ux*dy-uy*dx)/det;q.l[0]=1-q.l[1]-q.l[2];STJet N[ST_MAX];GfsMaterialPoint12 p;need(st_shape(t,q,N)&&st_point(t,m.f.coefficient.data(),N,&p),"CPU worst curvature full field");R D[4]={};for(int j=0;j<t.n;j++)for(int d=0;d<2;d++){D[2*d]+=a[d][t.id[j]]*N[j].x;D[2*d+1]+=a[d][t.id[j]]*N[j].y;}
    R x=q.X,y=q.Y,z=x*x+y*y+R(cfg.field.ic.eps)*cfg.field.ic.eps,o=powl(z,-.75L),o2=powl(z,-1.5L),B[4]={1.5L*x*y*o/z,-o+1.5L*y*y*o/z,o-1.5L*x*x*o/z,-1.5L*x*y*o/z},exact=-2*o2+3*(x*x+y*y)*o2/z-(B[0]*B[0]+2*B[1]*B[2]+B[3]*B[3]),actual=D[0]+D[3]-(R(p.grad_v[0])*p.grad_v[0]+2*R(p.grad_v[1])*p.grad_v[2]+R(p.grad_v[3])*p.grad_v[3]);point_out=q;return cfg.field.ic.gamma*fabsl(actual-exact)/o2;
}
static int curvature_from_saved(const std::string&saved,MPI_Comm comm,double gamma,double pressure,double eps){
    int rank,ranks;MPI_Comm_rank(comm,&rank);MPI_Comm_size(comm,&ranks);double begin=MPI_Wtime();MPI_Comm shared;MPI_Comm_split_type(comm,MPI_COMM_TYPE_SHARED,rank,MPI_INFO_NULL,&shared);int local_rank;MPI_Comm_rank(shared,&local_rank);MPI_Comm_free(&shared);int devices=0;need(cudaGetDeviceCount(&devices)==cudaSuccess&&devices>0&&cudaSetDevice(local_rank%devices)==cudaSuccess,"curvature actual GPU mapping");
    std::string suffix=std::to_string(rank);auto m=material_full::load_basis(saved+"/full_conditioned_basis_r"+suffix+".bin");md::Ownership layout(m.global,m.owner,comm);need(layout.global_owned==m.global_dofs,"restored full state owner count");
    FILE*f=fopen((saved+"/full_initial_acceleration_r"+suffix+".bin").c_str(),"rb");need(f,"actual saved initial acceleration");uint64_t h[4];material_full::read(f,h,4);need(h[0]==0x4d46414343454c31ULL&&h[1]==1&&h[2]==m.global.size()&&h[3]==sizeof(R),"actual full acceleration format");std::array<md::Vec,2>a={md::Vec(m.global.size()),md::Vec(m.global.size())};std::vector<STCoefficient>acc(m.global.size());for(int d=0;d<2;d++){material_full::read(f,a[d].data(),a[d].size());auto before=a[d];layout.pull(a[d]);need(before==a[d],"restored owner/ghost acceleration consistency");for(size_t j=0;j<acc.size();j++)acc[j].v[d]=double(a[d][j]);}need(fgetc(f)==EOF&&fclose(f)==0,"complete actual acceleration");
    GfsEnrichConfig cfg;config_rule(cfg,gamma,pressure,eps);Device gpu;need(mf_initial_create(m.f.triangle.data(),m.f.triangle.size(),m.f.coefficient.data(),m.f.coefficient.size(),m.rule.data(),&cfg,&gpu.ptr)==0&&mf_curvature_upload(gpu.ptr,acc.data(),acc.size())==0,"persistent GPU actual initial curvature");
    std::vector<MFCurvatureBlock>batch(MF_BATCH_TRIANGLES);std::vector<std::array<R,MF_CURV_METRICS>>cell(m.f.cell.size());std::vector<R>maximum(m.f.cell.size());R worst=0,minJ=1e99L,velocity_error=0;size_t worst_source=0;int worst_point=0;uint64_t points=0,nt=m.f.triangle.size(),maxnt;MPI_Allreduce(&nt,&maxnt,1,MPI_UINT64_T,MPI_MAX,comm);double kernel=0;
    FILE*raw=fopen(("full_curvature_blocks_r"+suffix+".bin").c_str(),"wbx");need(raw,"new full curvature blocks");uint64_t header[5]={0x4d46435552563031ULL,1,nt,sizeof(MFCurvatureBlock),uint64_t(rank)};material_full::write(raw,header,5);
    for(uint64_t at=0;at<maxnt;at+=MF_BATCH_TRIANGLES){size_t n=at<nt?std::min<uint64_t>(MF_BATCH_TRIANGLES,nt-at):0;int bad=0;try{if(n){double seconds;need(mf_curvature_batch(gpu.ptr,at,n,batch.data(),&seconds)==0,"actual whole-domain initial curvature kernel");kernel+=seconds;material_full::write(raw,batch.data(),n);for(size_t j=0;j<n;j++){auto&b=batch[j];need(b.bad_point<0&&b.minJ>0,"full initial curvature positive field");size_t c=m.f.triangle[at+j].cell;for(int k=0;k<MF_CURV_METRICS;k++)cell[c][k]+=value(b.metric[k]);maximum[c]=std::max(maximum[c],R(b.max_chi));if(b.max_chi>worst){worst=b.max_chi;worst_source=at+j;worst_point=b.max_chi_point;}minJ=std::min(minJ,R(b.minJ));velocity_error=std::max(velocity_error,R(b.max_velocity_error));points+=b.points;}}}catch(const std::exception&e){fprintf(stderr,"rank%d FULL_CURVATURE_FAIL %s\n",rank,e.what());bad=1;}int any;MPI_Allreduce(&bad,&any,1,MPI_INT,MPI_MAX,comm);if(any){material_full::durable(raw);return 2;}}
    material_full::durable(raw);auto geometry=gp::geometry(m.f);R max_mean=0,global[6]={};FILE*csv=fopen(("full_initial_curvature_cells_r"+suffix+".csv").c_str(),"wx");need(csv,"full cell initial curvature ledger");fprintf(csv,"cell,max_chi,mean_chi,U,K,Kdot,Udot,gravity_work,Ldot,gravity_torque,delta0,delta_dot\n");
    for(size_t c=0;c<cell.size();c++){need(cell[c][0]>0,"positive curvature source quadrature measure");R delta=(geometry.volume[c]-cell[c][2])/cell[c][0],deltadot=(geometry.vdot[c]-cell[c][3])/cell[c][0],U=pressure*geometry.volume[c]/(gamma-1),Udot=-R(pressure)*(cell[c][3]+deltadot*cell[c][0]),mean=cell[c][1]/cell[c][0];max_mean=std::max(max_mean,mean);global[0]+=U;global[1]+=cell[c][9];global[2]+=cell[c][5]+Udot-cell[c][7];global[3]+=cell[c][6]-cell[c][8];
        fprintf(csv,"%llu,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg\n",(unsigned long long)m.f.cell[c],maximum[c],mean,U,cell[c][9],cell[c][5],Udot,cell[c][7],cell[c][6],cell[c][8],delta,deltadot);
    }material_full::durable(csv);
    for(const auto&e:geometry.edge){uint64_t poly=m.global[e.reference.poly[1]];size_t id=(poly-m.global_vertices)/2;if(!m.external_edge[id])continue;need(e.side.size()==1,"physical external curvature side");for(int j=0;j<e.n;j++)for(int d=0;d<2;d++){int i=e.id[j];R force=-R(pressure)*e.side[0].sign*e.H[j][d];global[2]-=m.f.coefficient[i].v[d]*force;global[3]-=(d==1?m.f.coefficient[i].x[0]:-m.f.coefficient[i].x[1])*force;}}
    MPI_Allreduce(MPI_IN_PLACE,global,6,MPI_LONG_DOUBLE,MPI_SUM,comm);R maxima[4]={worst,max_mean,-minJ,velocity_error};MPI_Allreduce(MPI_IN_PLACE,maxima,4,MPI_LONG_DOUBLE,MPI_MAX,comm);uint64_t total=points;MPI_Allreduce(MPI_IN_PLACE,&total,1,MPI_UINT64_T,MPI_SUM,comm);
    STPoint witness;R cpu=curvature_witness(m,worst_source,worst_point,a,cfg,witness);FILE*w=fopen(("full_curvature_witness_r"+suffix+".json").c_str(),"wx");need(w,"independent CPU curvature worst-point witness");fprintf(w,"{\"rank\":%d,\"source_triangle\":%llu,\"cell\":%llu,\"compact_point\":%d,\"X\":%.17g,\"Y\":%.17g,\"radius\":%.17g,\"GPU_chi\":%.21Lg,\"CPU_binary80_chi\":%.21Lg,\"absolute_difference\":%.21Lg}\n",rank,(unsigned long long)m.source_triangle[worst_source],(unsigned long long)m.source_cell[worst_source],worst_point,witness.X,witness.Y,hypot(witness.X,witness.Y),worst,cpu,fabsl(worst-cpu));material_full::durable(w);
    R difference=fabsl(worst-cpu);MPI_Allreduce(MPI_IN_PLACE,&difference,1,MPI_LONG_DOUBLE,MPI_MAX,comm);bool pass=maxima[0]<=.002L&&maxima[1]<=.001L&&difference<1e-8L&&fabsl(global[2])/global[0]<1e-8L&&fabsl(global[3])/(2*global[1])<1e-11L;
    if(rank==0){FILE*out=fopen("full_initial_curvature_result.json","wx");need(out,"actual full initial curvature report");fprintf(out,"{\"scope\":\"all actual saved full material state and initial acceleration; streamed GPU initial curvature and point work audit, no mass replay or time evolution\",\"actual_positive_points\":%llu,\"max_chi\":%.21Lg,\"maximum_cell_mean_chi\":%.21Lg,\"original_chi_bound\":0.002,\"original_cell_mean_bound\":0.001,\"min_J\":%.21Lg,\"initial_velocity_error\":%.21Lg,\"CPU_binary80_worst_chi_absolute_difference\":%.21Lg,\"point_energy_rate_error_over_U\":%.21Lg,\"point_angular_rate_error_over_2K\":%.21Lg,\"CUDA_seconds_rank0\":%.9g,\"seconds\":%.9g,\"initial_curvature_and_global_work_pass\":%s,\"cell_local_hybrid_rate_audit_complete\":false,\"accepted_steps\":0,\"long_Kepler_validated\":false}\n",(unsigned long long)total,maxima[0],maxima[1],-maxima[2],maxima[3],difference,fabsl(global[2])/global[0],fabsl(global[3])/(2*global[1]),kernel,MPI_Wtime()-begin,pass?"true":"false");material_full::durable(out);}
    return pass?0:2;
}
